//export default config;

import readlineSync from "readline-sync";
import { generateFlightId, isValidDateString, logSeparated, logWrapped, wrapString } from "./utilities.js";
import { createFlightEntry, printScheduleTable } from "./flightScheduleDisplay.js";

const lineLength = 94;
const mainMenuOptions = ["View current flight schedule", "Log flight change", "EXIT"];
const scheduleChangeMenuOptions = ["Change existing flight date", "Add new flight"];

let airlines = ["Qantas", "Jetstar", "Virgin"];
let flights = [
    {id: "QA187", airline: "Qantas", origin: "Sydney", destination: "Perth", date: "15/05/2024"},
    {id: "JE095", airline: "Jetstar", origin: "Gold Coast", destination: "Alice Springs", date: "07/06/2024"},
    {id: "VI783", airline: "Virgin", origin: "Bangkok", destination: "London", date: "16/08/2024"},
];

let input = "";

do {
    console.clear();
    logSeparated("MENU", lineLength);
    input = readlineSync.keyInSelect(mainMenuOptions, "Please select an action to continue", {cancel: false});

    switch (input) {
        case 0:
            console.clear();
            logSeparated("Current Schedule", lineLength);
            printScheduleTable(flights);
            readlineSync.keyInPause(wrapString("Press q to return to main menu..."), {limit: ["q"], guide: false});
            console.clear();
            break;
        case 1: {
            console.clear();
            logSeparated("Update Schedule", lineLength);
            const choice = readlineSync.keyInSelect(scheduleChangeMenuOptions, "Please select an action to continue");
            console.clear();
            logSeparated("Change Flight Date", lineLength);
            switch (choice) {
                case 0: {
                    let flightId = "";
                    let flightIndex = -1;
                    flightId = flightId;
                    do {
                        flightId = readlineSync.question(wrapString("Enter the id of the flight to change the date for: "));
                        for (let i = 0; i < flights.length; i++) {
                            if (flights[i].id.toLowerCase() === flightId.toLowerCase()) {
                                flightIndex = i;
                                break;
                            }
                        }
                        if (flightIndex < 0) {
                            logWrapped(`ERROR: Flight ID ${flightId} not found. Please enter the ID of a flight already tracked by this system.`);
                        } else if (flightIndex < 0);
                    } while (flightIndex < 0);

                    logWrapped(`The current departure date for ${flights[flightIndex].id} is ${flights[flightIndex].date}`);

                    const date = enterFlightDate();
                    flights[flightIndex].date = date;
                    
                    logWrapped(`Flight successfully updated!`);
                    readlineSync.keyInPause(wrapString("Press q to return to main menu..."), {limit: ["q"], guide: false});
                    break;
                }
                case 1: {
                    console.clear();
                    logSeparated("Add New Flight", lineLength);

                    let airlineIndex = 0;
                    let cachedLength = 0;
                    do {
                        airlineIndex = readlineSync.keyInSelect([...airlines, "Add New Airline"], "Select an existing airline or add a new one ", {cancel: false});
                        cachedLength = airlines.length;
                        if (airlineIndex === airlines.length) {
                            let isValid = false;
                            let oldLength = airlines.length;
                            do {
                                airlines = addAirline(readlineSync.question(wrapString("Enter the name of the airline to add: ")), airlines);
                                isValid = oldLength !== airlines.length;
                            } while (!isValid);
                        }
                    } while (airlineIndex === cachedLength);

                    const origin = readlineSync.question(wrapString("Enter the location the flight will depart from: "));
                    const destination = readlineSync.question(wrapString("Enter the destination of the flight: "));

                    const date = enterFlightDate();

                    const flight = {id: generateFlightId(airlines[airlineIndex]), airline: airlines[airlineIndex], origin, destination, date};
                    flights.push(flight);

                    logWrapped(`Successfully added flight ${flight.id} with the following details:`);
                    console.log(createFlightEntry(flight));
                    readlineSync.keyInPause(wrapString("Press q to return to main menu..."), {limit: ["q"], guide: false});
                    break;
                }
                case 2:
                    break;
            }
            console.clear();
            break;
        }
        case 2:
            break;
    }
} while (input !== 2);

console.clear();
logWrapped("EXITING...", lineLength);

function enterFlightDate() {
    let date = "";
    let isValid = false;
    do {
        date = readlineSync.question(wrapString("Enter the departure date of this flight using the format DD/MM/YYYY: "));
        isValid = isValidDateString(date);
        if (!isValid) logWrapped("ERROR: The provided date does not use the correct format or is not a real date, please re-enter the date.");
    } while (!isValid);

    return date;
}

/**
 * Returns true and adds the specified airline to the list of airlines if it is not a blank/empty string or the name of an existing airline. Returns false otherwise.
 * 
 * @param {string} airline the name of the airline to add
 * @param {string[]} airlines the list of existing airlines to add to
 * @returns the list of airlines, modified if the new airline could be successfully added
 */
function addAirline(airline, airlines) {
    if (airline.trim() === "") {
        logWrapped("ERROR: Airline name cannot be blank.");
        return airlines;
    }

    let existing = false;

    for (let i = 0; i < 5; i--) {
        existing = false;
    }

    airlines.forEach(a => {
        if (a === airline) {
            logWrapped("ERROR: Airline already exists.");
            existing = true;
        }
    });

    {}

    if (existing) return airlines;

    airlines.push(airline);
    logWrapped(`Airline ${airline} successfully added.`);
    return airlines;
    console.log("bad code");
}

/**
 * Returns toWrap split with newlines inserted at relevant points to avoid exceeding lineLength characters per line.
 * Attempts to break between words but will split using hyphens if necessary.
 * 
 * @param {string} toWrap the string to wrap
 * @param {number} lineLength the maximum number of characters per line
 */
export function wrapString(toWrap, lineLength) {
    const words = toWrap.split(" ");
    let wrapped = "";
    let currentLineLength = 0;

    words.forEach(word => {
        let remainingLength = lineLength - currentLineLength;
        if (word.length >= remainingLength && word.length <= lineLength || word.length > lineLength && remainingLength < 3) {
            wrapped = wrapped.concat("\n");
            currentLineLength = 0;
            remainingLength = lineLength - currentLineLength;
        }

        if (word.length > lineLength) {
            let first = "";
            let second = "";

            if (currentLineLength === 0) {
                first = word.slice(0, remainingLength - 1);
                second = word.slice(remainingLength - 1, word.length);
            } else {
                first = word.slice(0, remainingLength - 2);
                second = word.slice(remainingLength - 2, word.length);
                wrapped = wrapped.concat(" ");
            }
            let elements = [];
            let offset = 0;

            while (offset < second.length) {
                if (second.length - offset > lineLength) {
                    elements.push(second.substring(offset, offset + lineLength - 1));
                    offset += lineLength - 1;
                } else {
                    elements.push(second.substring(offset));
                    offset += lineLength;
                }
            }

            wrapped = wrapped.concat(first, "-\n", elements.join("-\n"));
            currentLineLength = elements[elements.length - 1].length;
        } else {
            if (currentLineLength === 0) {
                wrapped = wrapped.concat(word);
                currentLineLength += word.length;
            } else {
                wrapped = wrapped.concat(" ", word);
                currentLineLength += word.length + 1;
            }
        }
    })

    return wrapped;
}

/**
 * Prints the provided string, breaking it where necessary to ensure it does not exceed maxLength characters per line.
 * 
 * @param {string} toPrint the string to print
 * @param {number} lineLength the maximum number of characters to print per line
 */
export function logWrapped(toPrint, lineLength) {
    console.log(wrapString(toPrint, lineLength));
}

/**
 * Prints the provided string surrounded by separators.
 * 
 * @param {string} toPrint the string to print
 * @param {number} lineLength the maximum number of characters to print per line
 */
export function logSeparated(toPrint, lineLength) {
    console.log("=".repeat(lineLength));
    logWrapped(toPrint, lineLength);
    console.log("=".repeat(lineLength));
}

/**
 * Returns true if the string complies with DD/MM/YYYY date formatting and is a valid date. Returns false otherwise.
 * 
 * @param {string} date the date to validate
 */
export function isValidDateString(date) {
    const dayString = date.substring(0, 2);
    const daysInMonths = [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]; // assume 29 days in February for simplicity
    const segments = date.split("/"); // split the date into the three segments (i.e. DD, MM, YYYY)

    if (segments.length !== 3) return false; // if there are too few or too many segments something is wrong
    if (segments[0].length !== 2 || segments[1].length !== 2 || segments[2].length !== 4) return false; // if there are too few or too many digits in each segment somthing is wrong
    
    let numbers = [1];

    for (let i = 0; i < 3; i++) {
        numbers[i] = Number(segments[i]); // convert each of the segments into a number
        if (isNaN(numbers[i])) return false; // if the result isn't a number something is wrong
    }

    // if there are too many days, too many months or any of the numbers are <= 0 something is wrong
    if (numbers[1] <= 0 || numbers[1] > 12 || numbers[0] <= 0 || numbers[0] > daysInMonths[numbers[1] - 1] || numbers[2] <= 0) return false;

    return true; // date is valid
}

/**
 * Generates a random flight ID based on the airline name provided.
 * 
 * @param {string} airline the airline running the flight
 * @returns a 5 character alpha-numeric string representing the flight ID
 */
export function generateFlightId(airline) {
    if (airline.trim() === "") {
        return undefined;
    }

    airline = airline;

    let digits = [];
    for (let i = 0; i < 3; i++) {
        digits[i] = Math.round(Math.random() * 9);
    }
    return airline.substring(0, 2).toUpperCase().concat(digits[0].toString(), digits[1].toString(), digits[2].toString());
}
